<script setup lang="ts">
/**
 * A bar chart for comparing magnitudes across categories (`design/components/bar-chart.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/bar-chart.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'

import {
  DEFAULT_CHART_MESSAGES,
  Icon,
  UNMEASURED,
  agentMember,
  barChartModel,
  barChartReadout,
  barChartSelection,
  chartHiddenSeries,
  chartMarks,
  chartPosition,
  chartSeries,
  chooseChartMark,
  createReading,
  createWarningLog,
  devWarning,
  measureBox,
  nearestIndex,
  readChartPosition,
  readingRest,
  readingView,
  toggleChartSeries,
  toggleSeries,
  useListening,
  type ChartAnnotation,
  type ChartBaseline,
  type ChartMessages,
  type ChartSeries,
  type ChartTooltipConfig,
  type ChartXAxis,
  type ChartYAxis,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/charts/bar-chart.module.css'
import a11y from '@polymorph/recipes/conventions/a11y.module.css'
import chartAxis from '@polymorph/recipes/charts/frame/chart-axis.module.css'
import chartFrame from '@polymorph/recipes/charts/frame/chart-frame.module.css'
import chartLegend from '@polymorph/recipes/charts/frame/chart-legend.module.css'
import chartNotes from '@polymorph/recipes/charts/frame/chart-annotations.module.css'
import chartTooltip from '@polymorph/recipes/charts/frame/chart-tooltip.module.css'
import chartTwin from '@polymorph/recipes/charts/frame/chart-twin.module.css'
import Button from '../controls/Button.vue'
import Table from '../structure/Table.vue'
import TableBody from '../structure/TableBody.vue'
import TableCell from '../structure/TableCell.vue'
import TableHead from '../structure/TableHead.vue'
import TableHeader from '../structure/TableHeader.vue'
import TableRow from '../structure/TableRow.vue'

export interface BarChartProps {
  /**
   * Annotations from the closed union above: line, band and point, literals only. The frame's
   * shared annotation layer draws them in `--pm-chart-axis`, with bands washed in
   * `--pm-chart-other` at 0.08. An annotation never re-centres colour. Colliding labels are
   * dropped, but the annotation itself always draws because the app asked for it explicitly.
   */
  annotations?: readonly ChartAnnotation[]
  baseline?: ChartBaseline
  /**
   * The data rows. `[]` renders the built-in empty state.
   */
  data: readonly Readonly<Record<string, string | number | null>>[]
  /**
   * Key of the series to emphasise. It keeps its slot colour and the rest use
   * `--pm-chart-other`. A status-toned series keeps its status colour, because reserved meaning
   * is never greyed out.
   */
  emphasis?: string
  /**
   * The chart's accessible name. It is required, as for Progress, because an unnamed chart tells
   * a reader nothing.
   */
  label: string
  /**
   * Series drawn as lines over the bars, on the bars' value axis and in their unit: a moving
   * average of the bars' own measure, say. They take the slots after the bars'. A vertical chart
   * only; a horizontal one warns and draws no lines. A second measure on a scale of its own is a
   * second chart.
   */
  lines?: readonly ChartSeries[]
  /**
   * Loading state. On first render the frame shows a quiet `Skeleton`; on refetch it shows the
   * previous frame at reduced opacity, with no layout jump or flash. Failure is not a chart
   * state: the app reports errors, and a chart shows only data, never network status.
   */
  loading?: boolean
  /**
   * The locale `Intl` formats with. When omitted, the runtime's own resolved locale applies.
   */
  locale?: string
  /**
   * The tier's message catalog. When omitted, the generic English defaults apply. A localized
   * host passes its own, the same object to every chart on the screen.
   */
  messages?: ChartMessages
  /**
   * How multiple series combine; applies at 2 or more series. Mixed signs cannot stack, so
   * `stacked` with both signs dev-warns and renders grouped. `diverging` is the Likert form on
   * `stackOffsetDiverging`. **The app splits neutral answers**: it pre-signs values, and the
   * member never derives a neutral key. Each side's segments take the diverging arms outward
   * from zero. In this mode the warning is reversed, because signed data is expected.
   */
  mode?: 'grouped' | 'stacked' | 'diverging'
  /**
   * Use horizontal for long category names, because the system never rotates a label.
   */
  orientation?: 'horizontal' | 'vertical'
  /**
   * The series to draw, 1–8. A ninth gets a dev-warning about folding into "Other", never a
   * generated hue, because the wheel has eight seats.
   */
  series: readonly ChartSeries[]
  /**
   * Frame height, from `--pm-chart-height-*`. The frame never nests a scroll region.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * Tooltip configuration, on with `'dot'` by default. `false`, for print and report surfaces,
   * removes only the visual layer.
   */
  tooltip?: false | ChartTooltipConfig
  x: ChartXAxis
  /**
   * Y axis configuration. The axis renders by default.
   */
  y?: ChartYAxis
}

defineOptions({ name: 'BarChart', inheritAttrs: false })

const props = withDefaults(defineProps<BarChartProps>(), {
  loading: false,
  messages: () => DEFAULT_CHART_MESSAGES,
  mode: 'grouped',
  orientation: 'vertical',
  size: 'md',
  tooltip: () => ({}),
})
const emit = defineEmits<{
  select: [
    selection: {
      index: number
      key: string
      datum: Readonly<Record<string, string | number | null>>
    },
  ]
}>()
const listening = useListening()
const box = ref(UNMEASURED)
const reading = ref(createReading({ count: 0, seriesStart: null }))
const position = ref(readingRest(null))
const hidden = ref(new Set<string>())
const twinOpen = ref(false)
const warningLog = ref(createWarningLog())
const frame = useTemplateRef<HTMLElement>('frame')
const plot = useTemplateRef<HTMLElement>('plot')
const input = computed(() => ({
  data: props.data,
  series: props.series,
  lines: props.lines,
  x: props.x,
  y: props.y,
  orientation: props.orientation,
  mode: props.mode,
  emphasis: props.emphasis,
  baseline: props.baseline,
  annotations: props.annotations,
  label: props.label,
  locale: props.locale,
  messages: props.messages,
  tooltip: props.tooltip,
  loading: props.loading,
  selectable: listening.select,
  hidden: hidden.value,
  box: box.value,
}))
const model = computed(() => barChartModel(input.value))
const view = computed(() =>
  readingView(position.value, props.data.length, model.value.visible.length),
)
const readout = computed(() => barChartReadout(input.value, model.value, view.value))
const activate = computed(() => () => {
  const selection = barChartSelection(input.value, model.value, reading.value.now())
  if (selection !== null) emit('select', selection)
})
const walk = computed(() => ({
  count: props.data.length,
  seriesCount: model.value.visible.length,
  walkSeries: true,
}))
const marks = computed(() => ({
  walk: walk.value,
  input: input.value,
  model: model.value,
  readout: barChartReadout,
  selection: barChartSelection,
}))
const onKey = computed(() => (event: KeyboardEvent) => {
  if (listening.select && (event.key === 'Enter' || event.key === ' ')) {
    event.preventDefault()
    activate.value()
    return
  }
  reading.value.update(walk.value)
  if (reading.value.key(event.key)) event.preventDefault()
})
const onPointer = computed(() => (event: PointerEvent) => {
  if (model.value.plot === null) return
  const rect = (event.currentTarget as Element).getBoundingClientRect()
  reading.value.moveTo(
    nearestIndex(
      model.value.positions,
      model.value.vertical ? event.clientX - rect.left : event.clientY - rect.top,
    ),
    reading.value.now().series,
  )
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const run = () => {
    box.value = plot.value === null ? box.value : measureBox(plot.value, box.value)
  }
  const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
  for (const element of [plot.value]) if (element) resize?.observe(element)
  release1 = () => {
    resize?.disconnect()
  }
  run()
}
onMounted(effect1)
onBeforeUnmount(() => release1?.())
const effect2 = () => {
  reading.value.subscribe((now) => {
    position.value = now
  })
}
onMounted(effect2)
const effect3 = () => {
  warningLog.value.log(model.value.warnings, (message) => devWarning(true, message))
}
onMounted(effect3)
watch(() => model.value.warnings.join('\n'), effect3, { flush: 'post' })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran =
    !listening.select && !model.value.legend
      ? () => {}
      : agentMember({
          member: 'BarChart',
          element: () => frame.value,
          state: () => ({
            items: listening.select ? chartMarks(marks.value, reading.value) : [],
            position: chartPosition(marks.value, reading.value),
            count: walk.value.count,
            series: chartSeries(frame.value, chartLegend.key, model.value.painted),
            hidden: chartHiddenSeries(frame.value, chartLegend.key, model.value.painted),
          }),
          actions: {
            read: {
              argument: 'number',
              run: (value) => readChartPosition(marks.value, value, reading.value),
            },
            choose: {
              argument: 'id',
              among: 'items',
              run: (value) => chooseChartMark(marks.value, value, reading.value, activate.value),
            },
            toggle: {
              argument: 'id',
              among: 'series',
              run: (value) =>
                toggleChartSeries(frame.value, chartLegend.key, model.value.painted, value),
            },
          },
        })
  release4 = () => {
    ran()
  }
}
onMounted(effect4)
onBeforeUnmount(() => release4?.())
</script>

<template>
  <figure
    ref="frame"
    :class="chartFrame.frame"
    :data-size="size"
    :data-state="model.state"
    :data-position="view.active ? view.index : undefined"
    :aria-label="label"
    data-member="bar-chart"
  >
    <!-- region -->
    <div :class="chartFrame.region">
      <!-- y axis -->
      <div :class="chartFrame.yAxis">
        <!-- y axis ticks -->
        <div
          v-if="model.axes?.y !== undefined"
          :class="chartAxis.axis"
          data-orientation="y"
          aria-hidden="true"
        >
          <template v-for="tick in model.axes?.y ?? []" :key="tick.key">
            <span :class="chartAxis.tick" :style="{ top: `${tick.at}px` }" :data-align="tick.align">
              {{ tick.label }}
            </span>
          </template>
        </div>
      </div>
      <!-- plot -->
      <div ref="plot" :class="chartFrame.plot">
        <div v-if="model.state === 'empty'" :class="chartFrame.empty">
          <span>
            {{ messages.empty }}
          </span>
        </div>
        <!-- surface -->
        <div
          v-else
          :class="styles.surface"
          tabindex="0"
          role="img"
          :aria-label="label"
          @keydown="onKey($event)"
          @click="activate()"
          @pointermove="onPointer($event)"
          @pointerleave="reading.clear()"
          @blur="reading.clear()"
        >
          <!-- marks -->
          <svg
            v-if="model.plot !== null"
            :class="styles.marks"
            :style="{ '--pm-chart-zero': `${model.plot?.zero}px` }"
            :data-orientation="orientation"
            :data-mode="model.drawn"
            :data-reading="view.active ? '' : undefined"
            :width="model.plot?.width"
            :height="model.plot?.height"
            aria-hidden="true"
            focusable="false"
          >
            <!-- grid -->
            <g :class="styles.grid">
              <template v-for="line in model.plot?.grid ?? []" :key="line.key">
                <path :d="line.d" />
              </template>
            </g>
            <!-- annotation wash -->
            <g v-if="(model.plot?.wash ?? []).length > 0" :class="chartNotes.washes">
              <template v-for="span in model.plot?.wash ?? []" :key="span.key">
                <rect
                  :class="chartNotes.span"
                  :x="span.x"
                  :y="span.y"
                  :width="span.width"
                  :height="span.height"
                />
              </template>
            </g>
            <!-- bands -->
            <g :class="styles.bands">
              <template v-for="band in model.plot?.bands ?? []" :key="band.key">
                <g :data-active="view.index === band.index ? '' : undefined">
                  <rect
                    :class="styles.hit"
                    :x="band.hit.x"
                    :y="band.hit.y"
                    :width="band.hit.width"
                    :height="band.hit.height"
                    @pointerenter="reading.moveTo(band.index, reading.now().series)"
                  />
                  <template v-for="mark in band.marks" :key="mark.key">
                    <path
                      :class="styles.bar"
                      :style="{ '--pm-chart-mark': mark.paint }"
                      :data-active="
                        view.index === band.index && view.series === mark.series ? '' : undefined
                      "
                      :d="mark.d"
                    />
                  </template>
                </g>
              </template>
            </g>
            <!-- zero -->
            <path :class="styles.zero" :d="model.plot?.zeroRule" />
            <!-- annotation ink -->
            <g v-if="(model.plot?.ink ?? null) !== null" :class="chartNotes.ink">
              <template v-for="span in (model.plot?.ink ?? null)?.spans ?? []" :key="span.key">
                <g>
                  <path :class="chartNotes.edge" :d="span.from" />
                  <path :class="chartNotes.edge" :d="span.to" />
                </g>
              </template>
              <template v-for="rule in (model.plot?.ink ?? null)?.rules ?? []" :key="rule.key">
                <path :class="chartNotes.rule" :d="rule.d" />
              </template>
              <template v-for="mark in (model.plot?.ink ?? null)?.marks ?? []" :key="mark.key">
                <circle :class="chartNotes.mark" :cx="mark.cx" :cy="mark.cy" :r="mark.r" />
              </template>
              <template v-for="note in (model.plot?.ink ?? null)?.labels ?? []" :key="note.key">
                <text :class="chartNotes.label" :x="note.x" :y="note.y" :text-anchor="note.anchor">
                  {{ note.text }}
                </text>
              </template>
            </g>
            <!-- lines -->
            <g v-if="(model.plot?.lines ?? []).length > 0" :class="styles.lines">
              <template v-for="line in model.plot?.lines ?? []" :key="line.key">
                <g :style="{ '--pm-chart-mark': line.paint }">
                  <path :class="styles.line" :d="line.d" />
                  <template v-for="point in line.points" :key="point.key">
                    <circle
                      :class="styles.point"
                      :cx="point.cx"
                      :cy="point.cy"
                      :r="point.r"
                      :data-active="
                        view.index === point.index &&
                        (view.series === null || view.series === line.series)
                          ? ''
                          : undefined
                      "
                    />
                  </template>
                </g>
              </template>
            </g>
          </svg>
        </div>
        <!-- tooltip -->
        <div
          v-if="readout.tooltip !== null"
          :class="chartTooltip.tooltip"
          :style="{
            '--pm-chart-tip-x': `${readout.tooltip?.x}px`,
            '--pm-chart-tip-y': `${readout.tooltip?.y}px`,
          }"
          :data-indicator="readout.tooltip?.indicator"
          :data-side="readout.tooltip?.side"
          aria-hidden="true"
        >
          <p v-if="readout.tooltip?.header !== undefined" :class="chartTooltip.header">
            {{ readout.tooltip?.header }}
          </p>
          <ul :class="chartTooltip.rows">
            <template v-for="row in readout.tooltip?.rows ?? []" :key="row.key">
              <li :class="chartTooltip.row">
                <span :class="chartTooltip.key" :style="{ '--pm-chart-key': row.paint }" />
                <span :class="chartTooltip.value">
                  {{ row.value }}
                </span>
                <span :class="chartTooltip.label">
                  {{ row.label }}
                </span>
              </li>
            </template>
          </ul>
        </div>
      </div>
      <!-- x axis -->
      <div :class="chartFrame.xAxis">
        <!-- x axis ticks -->
        <div
          v-if="model.axes?.x !== undefined"
          :class="chartAxis.axis"
          data-orientation="x"
          aria-hidden="true"
        >
          <template v-for="tick in model.axes?.x ?? []" :key="tick.key">
            <span
              :class="chartAxis.tick"
              :style="{ left: `${tick.at}px` }"
              :data-align="tick.align"
            >
              {{ tick.label }}
            </span>
          </template>
        </div>
      </div>
    </div>
    <template v-if="model.legend">
      <!-- legend -->
      <ul v-if="model.painted.length > 0" :class="styles.legend" data-key-shape="rect">
        <template v-for="entry in model.painted" :key="entry.key">
          <li
            :class="chartLegend.item"
            :data-key-shape="model.lineKeys.includes(entry.key) ? 'line' : undefined"
          >
            <button
              :class="chartLegend.key"
              type="button"
              :aria-pressed="hidden.has(entry.key) ? 'false' : 'true'"
              @click="hidden = toggleSeries(hidden, entry.key)"
            >
              <span
                :class="chartLegend.swatch"
                :style="{ '--pm-chart-key': entry.paint }"
                aria-hidden="true"
              />
              <span v-if="entry.icon !== undefined" :class="chartLegend.glyph">
                <Icon :name="entry.icon" size="sm" />
              </span>
              <span :class="chartLegend.label">
                {{ entry.label }}
              </span>
            </button>
          </li>
        </template>
      </ul>
    </template>
    <!-- summary -->
    <span :class="a11y.visuallyHidden">
      {{ model.summary }}
    </span>
    <!-- twin -->
    <div :class="chartTwin.twin" :data-state="twinOpen ? 'open' : 'closed'">
      <div :class="chartTwin.toggle">
        <Button
          variant="ghost"
          tone="neutral"
          size="sm"
          icon="table"
          :iconOnly="true"
          :label="twinOpen ? messages.hideTable(label) : messages.showTable(label)"
          @click="twinOpen = !twinOpen"
        />
      </div>
      <div v-if="twinOpen" :class="chartTwin.table">
        <Table :label="messages.tableLabel(label)" :caption="messages.tableLabel(label)">
          <TableHead>
            <TableRow>
              <template v-for="column in model.twin.columns" :key="column.key">
                <TableHeader :numeric="column.numeric">
                  {{ column.label }}
                </TableHeader>
              </template>
            </TableRow>
          </TableHead>
          <TableBody>
            <template v-for="(row, line) in model.twin.rows" :key="line">
              <TableRow>
                <template
                  v-for="(cell, cellIndex) in row"
                  :key="model.twin.columns[cellIndex]?.key ?? cellIndex"
                >
                  <TableCell :numeric="model.twin.columns[cellIndex]?.numeric">
                    {{ cell === '' ? '—' : cell }}
                  </TableCell>
                </template>
              </TableRow>
            </template>
          </TableBody>
        </Table>
      </div>
    </div>
    <!-- live region -->
    <span :class="a11y.visuallyHidden">
      <div aria-live="polite" aria-atomic="true">
        {{ readout.announcement }}
      </div>
    </span>
  </figure>
</template>
